#include <bits/stdc++.h>
using namespace std;
using ll = long long;
using pii = pair<int, int>;

struct Edge {
    int to, rev;
    ll capacity, flow;
    Edge(int t, int r, ll c) : to(t), rev(r), capacity(c), flow(0) {}
};

struct Dinic {
    int n, source, sink;
    vector<vector<Edge>> graph;
    vector<int> level, ptr;
    queue<int> q;

    Dinic(int nodes, int s, int e) : n(nodes), source(s), sink(e) {
        graph.resize(n);
        level.resize(n);
        ptr.resize(n);
    }

    void addEdge(int u, int v, ll cap) {
        graph[u].emplace_back(v, graph[v].size(), cap);
        graph[v].emplace_back(u, graph[u].size() - 1, 0);
    }

    bool bfs() {
        fill(level.begin(), level.end(), -1);
        level[source] = 0;
        q.push(source);
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (auto& e : graph[u]) {
                if (e.capacity - e.flow > 0 && level[e.to] == -1) {
                    level[e.to] = level[u] + 1;
                    q.push(e.to);
                }
            }
        }
        return level[sink] != -1;
    }

    ll dfs(int u, ll flow) {
        if (u == sink) return flow;
        for (int& i = ptr[u]; i < (int)graph[u].size(); ++i) {
            Edge& e = graph[u][i];
            if (level[e.to] == level[u] + 1 && e.capacity - e.flow > 0) {
                ll pushed = dfs(e.to, min(flow, e.capacity - e.flow));
                if (pushed > 0) {
                    e.flow += pushed;
                    graph[e.to][e.rev].flow -= pushed;
                    return pushed;
                }
            }
        }
        return 0;
    }

    ll maxFlow() {
        ll total = 0;
        while (bfs()) {
            fill(ptr.begin(), ptr.end(), 0);
            while (ll pushed = dfs(source, numeric_limits<ll>::max())) {
                total += pushed;
            }
        }
        return total;
    }
};

int distToFire[150][150], distToExit[150][150];
int cellIndex[150][150];
int n, T;
vector<string> grid, exits;

vector<pii> neighbors(int r, int c) {
    vector<pii> res;
    if (r+1 < n) res.emplace_back(r+1, c);
    if (r-1 >= 0) res.emplace_back(r-1, c);
    if (c+1 < n) res.emplace_back(r, c+1);
    if (c-1 >= 0) res.emplace_back(r, c-1);
    return res;
}

void computeFireDist(int sr, int sc) {
    queue<pii> bfs;
    memset(distToFire, -1, sizeof(distToFire));
    distToFire[sr][sc] = 0;
    bfs.push({sr, sc});
    while (!bfs.empty()) {
        auto [r, c] = bfs.front(); bfs.pop();
        for (auto [nr, nc] : neighbors(r, c)) {
            if (grid[nr][nc] != 'Z' && !isdigit(grid[nr][nc]) && distToFire[nr][nc] == -1) continue;
            if (distToFire[nr][nc] == -1 || distToFire[nr][nc] > distToFire[r][c] + 1) {
                distToFire[nr][nc] = distToFire[r][c] + 1;
                bfs.push({nr, nc});
            }
        }
    }
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (isdigit(grid[i][j]) && distToFire[i][j] == -1)
                distToFire[i][j] = T;
}

void computeExitDist(int sr, int sc) {
    queue<pii> bfs;
    memset(distToExit, -1, sizeof(distToExit));
    distToExit[sr][sc] = 0;
    bfs.push({sr, sc});
    while (!bfs.empty()) {
        auto [r, c] = bfs.front(); bfs.pop();
        for (auto [nr, nc] : neighbors(r, c)) {
            if (!isdigit(grid[nr][nc]) || distToExit[nr][nc] != -1) continue;
            distToExit[nr][nc] = distToExit[r][c] + 1;
            bfs.push({nr, nc});
        }
    }
}

int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    cin >> n >> T;
    grid.resize(n); exits.resize(n);
    for (int i = 0; i < n; ++i) cin >> grid[i];
    for (int i = 0; i < n; ++i) cin >> exits[i];

    int fireR = -1, fireC = -1;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            cellIndex[i][j] = i * n + j + 1;
            if (grid[i][j] == 'Z') {
                fireR = i;
                fireC = j;
            }
        }
    }

    computeFireDist(fireR, fireC);

    int totalNodes = n * n * 2 + 2;
    int source = 0, sink = totalNodes - 1;
    Dinic flowNet(totalNodes, source, sink);

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (isdigit(grid[i][j])) {
                int people = grid[i][j] - '0';
                flowNet.addEdge(source, cellIndex[i][j], people);
                computeExitDist(i, j);
                for (int r = 0; r < n; ++r) {
                    for (int c = 0; c < n; ++c) {
                        if (isdigit(exits[r][c]) && distToExit[r][c] != -1 &&
                            distToExit[r][c] <= distToFire[r][c] &&
                            distToExit[r][c] <= T) {
                            bool allow = true;
                            if (distToExit[r][c] == distToFire[r][c]) {
                                allow = false;
                                for (auto [nr, nc] : neighbors(r, c)) {
                                    if (distToExit[nr][nc] != -1 &&
                                        distToExit[nr][nc] < distToFire[nr][nc]) {
                                        allow = true;
                                        break;
                                    }
                                }
                            }
                            if (allow) {
                                flowNet.addEdge(cellIndex[i][j], n * n + cellIndex[r][c], people);
                            }
                        }
                    }
                }
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (isdigit(exits[i][j])) {
                int capacity = exits[i][j] - '0';
                flowNet.addEdge(n * n + cellIndex[i][j], sink, capacity);
            }
        }
    }

    cout << flowNet.maxFlow() << '\n';
}
